PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate
WHERE {
  VALUES ?film { dbr:Toen_'t_licht_verdween dbr:Boum_sur_Paris }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director's death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?d1 . }
  OPTIONAL { ?director dbo:deathDate ?d2 . }
  BIND (COALESCE(?d1, ?d2) AS ?deathDate)

  # readable labels
  BIND (STRAFTER(STR(?film), "resource/") AS ?filmLabel)
  BIND (STRAFTER(STR(?director), "resource/") AS ?directorLabel)
}
LIMIT 100
